#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# Conservative dotenv subset when the project's parser is not specified:
# KEY=bare-value, blank lines and whole-line comments. No quoting, whitespace
# in values, interpolation, escapes or multiline values. Requires Python 3.
# Never source/eval an env file. Read status: 0 found, 1 absent, 2 unsafe/error.
_env_io() {
  if ! command -v python3 >/dev/null 2>&1; then
    printf 'ERROR: Python 3 is required for safe .env handling.\n' >&2
    return 2
  fi
  python3 - "$1" "$ENV_FILE" "$2" <<'PY'
import os
import re
import stat
import sys
import tempfile
from pathlib import Path

class EnvError(Exception):
    pass

KEY = re.compile(r'[A-Za-z_][A-Za-z0-9_]*\Z', re.ASCII)
VALUE = re.compile(r'[A-Za-z0-9_./:@%+=,-]*\Z', re.ASCII)
mode, filename, key = sys.argv[1:]
temporary = None
try:
    if mode not in ('read', 'write') or not KEY.fullmatch(key):
        raise EnvError('Invalid .env operation or variable name.')
    value = None
    if mode == 'write':
        # The Bash here-string adds exactly one newline. FD 3 avoids placing
        # the value in process arguments or environment variables.
        with os.fdopen(3, 'rb') as incoming:
            raw_value = incoming.read()
        if not raw_value.endswith(b'\n'):
            raise EnvError('Invalid value transport.')
        value = raw_value[:-1].decode('utf-8')
        if not VALUE.fullmatch(value):
            raise EnvError('Ambiguous .env value: only simple single-line bare values are supported. Use a project-specific parser for other values.')
    path = Path(filename)
    original = None
    data = b''
    try:
        original = path.lstat()
    except FileNotFoundError:
        pass
    if original is not None:
        if not stat.S_ISREG(original.st_mode):
            raise EnvError('.env must be a regular file, not a symlink or directory.')
        fd = os.open(path, os.O_RDONLY | getattr(os, 'O_NOFOLLOW', 0))
        with os.fdopen(fd, 'rb') as source:
            opened = os.fstat(source.fileno())
            if (opened.st_dev, opened.st_ino) != (original.st_dev, original.st_ino):
                raise EnvError('.env changed while opening; retry after reviewing it.')
            data = source.read()
    text = data.decode('utf-8')
    if any(c in text for c in '\x00\x0b\x0c\x1c\x1d\x1e\x85\u2028\u2029') or re.search(r'\r(?!\n)', text):
        raise EnvError('Unsupported control characters in .env; file was not changed.')
    # Keep existing newline style and all unrelated accepted lines verbatim.
    lines = text.splitlines(keepends=True)
    values = {}
    positions = {}
    for index, raw_line in enumerate(lines):
        line = raw_line.removesuffix('\n').removesuffix('\r')
        if not line.strip(' \t') or line.lstrip(' \t').startswith('#'):
            continue
        name, separator, existing = line.partition('=')
        if not separator or not KEY.fullmatch(name) or not VALUE.fullmatch(existing):
            raise EnvError('Unsupported .env syntax; file was not changed. Configure its actual parser before editing.')
        if name in values:
            raise EnvError('Duplicate .env variable names; resolve them before editing.')
        values[name], positions[name] = existing, index
    if mode == 'read':
        if key not in values:
            sys.exit(1)
        sys.stdout.write(values[key])
        sys.exit(0)
    newline = '\r\n' if b'\r\n' in data else '\n'
    replacement = key + '=' + value + newline
    if key in positions:
        lines[positions[key]] = replacement
    else:
        if lines and not lines[-1].endswith('\n'):
            lines[-1] += newline
        lines.append(replacement)
    output = ''.join(lines).encode('utf-8')
    if original is not None and output == data:
        sys.exit(0)
    # Same-directory temp + replace avoids truncation on partial writes and
    # cross-filesystem rename. New files are private; existing mode is kept.
    fd, temporary = tempfile.mkstemp(prefix='.' + path.name + '.wizard-', dir=path.parent)
    with os.fdopen(fd, 'wb') as destination:
        if original is not None:
            os.fchmod(destination.fileno(), stat.S_IMODE(original.st_mode))
        destination.write(output)
        destination.flush()
        os.fsync(destination.fileno())
    try:
        current = path.lstat()
    except FileNotFoundError:
        current = None
    signature = lambda s: None if s is None else (s.st_dev, s.st_ino, s.st_size, s.st_mtime_ns, s.st_ctime_ns)
    if signature(current) != signature(original):
        raise EnvError('.env changed during the update; retry after reviewing it.')
    os.replace(temporary, path)
    temporary = None
except EnvError as exc:
    print('ERROR: ' + str(exc), file=sys.stderr)
    sys.exit(2)
except (OSError, UnicodeError, ValueError):
    # Do not expose a value or raw exception text in logs.
    print('ERROR: .env read/write failed; update was not completed.', file=sys.stderr)
    sys.exit(2)
except Exception:
    print('ERROR: unexpected .env processing failure; update was not completed.', file=sys.stderr)
    sys.exit(2)
finally:
    if temporary is not None:
        try:
            os.unlink(temporary)
        except OSError:
            print('ERROR: could not remove temporary .env file; manual cleanup is required.', file=sys.stderr)
PY
}

# _existing KEY: 1 means absent only; parse and IO failures return 2.
_existing() {
  _env_io read "$1"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input rc
  if current=$(_existing "$key"); then
    :
  else
    rc=$?
    [[ "$rc" -eq 1 ]] || return "$rc"
    current=""
  fi
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || { printf "ERROR: input could not be read.\n" >&2; return 2; }
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc
  if current=$(_existing "$key"); then
    :
  else
    rc=$?
    [[ "$rc" -eq 1 ]] || return "$rc"
    current=""
  fi
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || { printf "ERROR: input could not be read.\n" >&2; return 2; }
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE: atomic upsert of the same bare format _existing reads.
# Refuse ambiguous input or any unsupported existing syntax before mutation.
write_env() {
  local key="$1" value="$2"
  if _env_io write "$key" 3<<<"$value"; then
    WRITTEN_ENV+=("$key")
    printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
  else
    return 2
  fi
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=1

banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
